# Generated by Descant: acceptance tests.
# frozen_string_literal: true

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots stale-generation refusal record", type: :request do
  it "records a refusal row with a nil handoff step for a 409 stale_generation delivered over HTTP outside a handoff, and the freeze step for one refused during a handoff" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    entry_id = 90_701

    stale_item = lambda do |outbox_position|
      entry = TimekeepingSnapshots.entry(id: entry_id, company_id: company.id, version: 1, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.item(entry, generation: 1, outbox_position:)
    end

    with_timekeeping_service_token do |token|
      deliver = lambda do |snapshot|
        post "/internal/v1/timekeeping/entry-snapshots",
          params: TimekeepingSnapshots.batch(snapshot).to_json,
          headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json",
                     "Idempotency-Key" => SecureRandom.uuid }
      end

      # "any `409 stale_generation` outside a handoff;" needs a lasting record of the refusal, because the
      # refused batch's transaction rolls back and would otherwise leave no trace for timekeeping:alerts.
      TimekeepingOwnership.current.update!(generation: 2, handoff_step: nil)
      expect(TimekeepingStaleGenerationRefusal.count).to eq(0)

      deliver.call(stale_item.call(5))
      expect(response).to have_http_status(409)
      expect(response.parsed_body).to eq("reason" => "stale_generation")
      expect(TimekeepingStaleGenerationRefusal.pluck(:company_id, :handoff_step)).to eq([[company.id, nil]])

      # A refusal during a handoff is recorded with that step, so the alert can leave it out.
      TimekeepingOwnership.current.update!(handoff_step: "freeze", final_outbox_position: 10)
      deliver.call(stale_item.call(11))
      expect(response).to have_http_status(409)
      expect(TimekeepingStaleGenerationRefusal.order(:id).pluck(:company_id, :handoff_step))
        .to eq([[company.id, nil], [company.id, "freeze"]])
    end

    expect(TimesheetEntry.with_discarded.find_by(id: entry_id)).to be_nil
  end
end
